import json
from pathlib import Path
P=Path(__file__).resolve().parent
rs=json.loads((P/'remaining-initial.json').read_text());done={x['Form_ID'] for f in P.glob('pass*-saved-assignments.json') for x in json.loads(f.read_text())}
groups=[{'parent': '135', 'gloss': ['finger'], 'forms': ['aŋgūl', 'āŋgul', 'aŋgul', 'āŋgu', 'āŋgū', 'aŋgun', 'amuli', 'āŋḷhi'], 'citation': 'CDIAL[135,1 and addenda]', 'evidence': 'Turner’s first aṅguli branch gives Punjabi aṅgul/uṅgul, Gujarati ā̃gḷī, Bengali āṅul and Nepali aũli with compound amal-. These survey finger forms fit that branch, including the contracted western āŋgu and Majhi amuli; the aṅgula measure-of-length entry (134) and Dardic aṅgūḍi branch are excluded. Hajong final n and Vasavi aspiration are retained as regional qualifications.'}, {'parent': '135-2x', 'gloss': ['finger'], 'forms': ['hāgvī'], 'languages': ['Chil'], 'citation': 'CDIAL[135,2]', 'evidence': 'Turner’s aṅgūḍi branch explicitly lists Maiya agui/aṅgui and Shina Kohistani haṅui, beside Jijel háguṛi. Chiliss hāgvī fits this northern h-initial contracted series with the vowel/glide written v; it is kept separate from the first aṅguli branch used for the southern survey forms.'}, {'parent': '5239', 'gloss': ['body'], 'forms': ['jʸu'], 'languages': ['Majhi', 'Bote'], 'citation': 'CDIAL[5239]', 'evidence': 'Turner explicitly records Nepali jiu body/life and Kumaoni jyū life/soul under jīva. Majhi and Bote jyu body match this coalesced regional noun; the distinct jīva honorific-particle entry is not selected.'}, {'parent': '5536-3', 'gloss': ['body'], 'forms': ['ḍiḷ'], 'languages': ['Noiri', 'PauriBareli', 'RathwiBareli'], 'citation': 'CDIAL[5536,3]', 'evidence': 'Turner’s third branch *ḍilla gives Gujarati ḍīl body and Sindhi ḍīlu belly/body. The western survey retroflex ḍiḷ responses match that branch. The plain dental dil form belongs to Turner’s distinct tenth branch, while ḍin forms need an independent account of the final nasal and remain excluded.'}, {'parent': '5536-10', 'gloss': ['body'], 'forms': ['dīl'], 'languages': ['Bhili'], 'citation': 'CDIAL[5536,10]', 'evidence': 'Turner explicitly separates dental *dilla, including Gujarati dil body/belly, from retroflex *ḍilla. Bhili dīl body is placed in the dental tenth branch as transcribed, with its long vowel retained.'}, {'parent': '4124', 'gloss': ['body'], 'forms': ['gāṭ', 'gātʰ', 'ga'], 'languages': ['kaithal', 'Goj', 'B'], 'citation': 'CDIAL[4124]', 'evidence': 'Turner gives Hindi/Western Pahari gāt body, Nepali gāth person/body and Bengali gā body under gātra. The Haryanvi gāṭ, Gujari gāth and Bengali ga responses fit these regional shapes. The short responses are not assigned to the separate gātraka family with an additional suffix.'}, {'parent': '6712', 'gloss': ['body'], 'forms': ['dhaḍ', 'ḍhaḍ'], 'languages': ['RathwiBareli'], 'citation': 'CDIAL[6712]', 'evidence': 'Turner includes Gujarati dhaṛ and Marathi dhaḍ trunk/body under *dhaḍa. Rathwi dhaḍ/ḍhaḍ match this western body noun, preserving the survey’s variable initial dental/retroflex spelling. The longer dhaḍāṅgaka reconstruction is not needed.'}, {'parent': '2757', 'gloss': ['elbow'], 'forms': ['kūṇī', 'koṇī', 'kūṇī / kuṇī', 'kuhuŋi'], 'citation': 'CDIAL[2757 and addenda]', 'evidence': 'Turner gives Gujarati kɔṇī, Kotgarhi kvṇi and Punjabi kūhṇī elbow, beside Prakrit kuhaṇī. The Mewari/Gujari contracted forms and Rathwi kuhuŋi fit this family; the latter’s velar nasal is a regional qualification. Both Gujari slash alternatives are vowel-length variants of the same word.'}, {'parent': '4354', 'gloss': ['elbow'], 'forms': ['gā̃ṭī', 'gā̃ṇṭʰ', 'gā̃ṭ'], 'languages': ['Dang'], 'citation': 'CDIAL[4354]', 'evidence': 'Turner identifies granthi as knot/joint and lists Hindi gā̃ṭh/gā̃ṭhī and Marathi/Gujarati gā̃ṭh. These Dang elbow answers name the joint using that same family; the semantic narrowing is stated explicitly, not confused with the distinct elbow roots kaphōṇi or kūrpara.'}]
a=[]
for i,g in enumerate(groups):
 for r in rs:
  if r['ID'] not in done and r['Gloss'] in g['gloss'] and r['Form'] in g['forms'] and ('languages' not in g or r['Language_ID'] in g['languages']):
   a.append(dict(record=r,parent=g['parent'],kind='reflex',citation=g['citation'],evidence=g['evidence'],family=i))
assert len(a)==len({x['record']['ID'] for x in a})
h=[]
(P/'pass045-decisions.json').write_text(json.dumps(dict(accepted=a,held=h),ensure_ascii=False,indent=1)+'\n')
(P/'pass045-rules.json').write_text(json.dumps(groups,ensure_ascii=False,indent=1)+'\n')
print(len(a),'accepted',len(h),'held',[(g['parent'],sum(x['family']==i for x in a)) for i,g in enumerate(groups)])
